import json

with open('dev_requests.json') as f:
    dev = json.load(f)

reqs = dev['3A']

fields = ['time_min', 'age', 'mass', 'height', 'skin_temp', 'hr', 'watts', 'ambient_temp', 'humidity']
missing_counts = {f: 0 for f in fields}
total_rows = 0

for req in reqs:
    for row in req['history']:
        total_rows += 1
        for f in fields:
            if row[f] is None:
                missing_counts[f] += 1

print(f"Total rows across dev 3A histories: {total_rows}")
for f, count in missing_counts.items():
    print(f"  {f}: {count}/{total_rows} missing ({count/total_rows*100:.1f}%)")
