import json

with open('train.json') as f:
    train = json.load(f)

for pid, series in sorted(train.items()):
    watts = [r['watts'] for r in series]
    drops = []
    for i in range(1, len(watts)):
        if watts[i] < watts[i-1]:
            drops.append((i, series[i]['time_min'], watts[i-1], watts[i]))
    if drops:
        print(f"Train {pid}: drops = {drops}")

with open('dev_requests.json') as f:
    dev = json.load(f)

print("\nDev 3A people watts profiles:")
# Check each distinct person
people_watts = {}
for req in dev['3A']:
    h0 = req['history'][0]
    pkey = (h0['age'], h0['mass'], h0['height'])
    if pkey not in people_watts or len(req['history']) > len(people_watts[pkey]):
        people_watts[pkey] = [r['watts'] for r in req['history']]

for pkey, wprof in people_watts.items():
    drops = []
    for i in range(1, len(wprof)):
        if wprof[i] < wprof[i-1]:
            drops.append((i, wprof[i-1], wprof[i]))
    print(f"Dev {pkey}: drops = {drops}, final watts = {wprof[-1]}")
"]}

